def _load_detector(filename, module_name):
    path=Path(__file__).resolve().parent/'anomaly-detector'/filename
    spec=importlib.util.spec_from_file_location(module_name,path)
    module=importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
    return module

CLASSIC=_load_detector('classic.py','hvac_classic_detector').ClassicDetector()
AI_BASED=_load_detector('ai-based.py','hvac_ai_detector').AdaptiveDetector()

def anomaly_detection(reading):
    classic=CLASSIC.process(reading); ai=AI_BASED.process(reading)
    grouped={}
    for source in (classic.get('alerts',[]),ai.get('alerts',[])):
        for alert in source:
            key=(alert.get('component'),alert.get('fault_mode')); grouped.setdefault(key,[]).append(alert)
    alerts=[]
    for (component,mode),matches in grouped.items():
        agreement=len({x['detector'] for x in matches})>1; strongest=max(matches,key=lambda x:x['risk_score'])
        seconds=[x.get('estimated_time_remaining_seconds') for x in matches if x.get('estimated_time_remaining_seconds')]
        risk=min(100,round(sum(x['risk_score'] for x in matches)/len(matches)+(10 if agreement else 0)))
        confidence=min(98,round(sum(x['confidence'] for x in matches)/len(matches)+(12 if agreement else -8)))
        remaining=min(seconds) if seconds else None
        remaining_label=('Monitoring' if remaining is None else (f"~{round(remaining)} sec · simulation estimate" if remaining<60 else f"~{round(remaining/60)} min · simulation estimate"))
        alerts.append({'detector':'hybrid','method':'classic + adaptive agreement','component':component,'fault_mode':mode,
            'severity':'critical' if risk>=80 else 'warning' if risk>=55 else 'advisory','risk_score':risk,'confidence':max(1,confidence),
            'estimated_time_remaining_seconds':remaining,'estimated_time_remaining':remaining_label,
            'evidence':list(dict.fromkeys(e for x in matches for e in x.get('evidence',[])))[:4],
            'recommendation':strongest['recommendation'],'timestamp':reading.get('timestamp'),'status':'agreement' if agreement else 'single_detector',
            'detector_agreement':agreement})
    hybrid={'detector':'hybrid','status':'alerting' if alerts else 'monitoring','model_status':'agreement_fusion','last_analysis_time':reading.get('timestamp'),'alerts':alerts}
    return {'classic':classic,'ai_based':ai,'hybrid':hybrid}

