def nav():
    return f'<header class="topbar"><nav class="nav shell"><a class="brand" href="/assets">{mark()}<span>Neural Mech</span></a><span class="context">Asset registry</span><span class="system"><i class="pulse"></i> System nominal</span></nav></header>'

def page(title, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f2f0e9"><title>{escape(title)} · Neural Mech</title><style>{CSS}</style></head><body>{nav()}{body}<footer class="site-footer"><div class="shell"><span>Neural Mech / Facility Systems</span><span>Registry ready for expansion</span></div></footer></body></html>'''.encode()

def assets_page():
    return page('Assets', f'''<main><section class="hero shell"><div><p class="eyebrow">Facility inventory / 01</p><h1>Assets</h1></div><div class="hero-copy"><p>Operational equipment, mapped into one precise view. Select an asset to inspect its digital twin.</p><div class="count"><span>Registered units</span><strong>01</strong></div></div></section><section class="registry shell"><div class="registry-head"><span>Active registry</span><span>1 result</span></div><a class="asset" href="/digital-twin/HVAC-001"><div class="asset-info"><span class="asset-kicker">Air systems / AHU</span><h2>HVAC-001</h2><span class="asset-type">Primary air handling unit</span><div class="facts"><div class="fact"><span>Location</span><strong>Plant Room · Level 01</strong></div><div class="fact"><span>Operating state</span><strong class="status">Nominal</strong></div></div></div><div class="asset-visual">{hvac()}</div></a></section></main>''')

def digital_twin_page(asset_id):
    sid = escape(asset_id)
    if asset_id != 'HVAC-001':
        return page(f'Digital Twin — {asset_id}', f'<main class="shell notfound"><p class="eyebrow">Digital twin</p><h1>{sid}</h1><p>No telemetry integration is configured for this asset.</p><a class="back" href="/assets">← Asset registry</a></main>')
    labels=[('supply_air_temperature','Supply air'),('return_air_temperature','Return air'),('airflow','Airflow'),('filter_differential_pressure','Filter ΔP'),('motor_current','Motor current'),('fan_vibration','Fan vibration'),('temperature_setpoint','Setpoint')]
    tiles=''.join(f'<article class="metric"><span class="metric-label"><i class="led"></i>{label}</span><strong class="metric-value" data-value="{key}">—<small class="unit"></small></strong><span class="severity" data-severity="{key}">Connecting</span></article>' for key,label in labels)
    charts=[('temperature','Temperature profile','supply_air_temperature,return_air_temperature,temperature_setpoint','°C'),('','Airflow','airflow','m³/h'),('','Filter pressure','filter_differential_pressure','Pa'),('','Motor current','motor_current','A'),('','Fan vibration','fan_vibration','mm/s')]
    graph_html=''.join(f'''<article class="chart {cls}"><h2>{title}</h2><span class="chart-meta"><span class="chart-window">1 minute</span> · {unit}<span class="range-state"></span></span><svg class="plot" data-series="{series}" viewBox="0 0 600 215" preserveAspectRatio="none" role="img" aria-label="{title} live graph with zero-based engineering scale"><text class="chart-empty" x="48" y="100">CONNECTING TO TELEMETRY…</text></svg><div class="legend">{('<span class="key">Supply live</span><span class="key alt">Return live</span><span class="key set">Setpoint live</span>' if cls else '<span class="key">Live reading</span>')}<span class="key baseline-key">Engineering baseline</span></div></article>''' for cls,title,series,unit in charts)
    faults=[('filter_clog','Clogged filter','Rising pressure · reduced airflow'),('coil_fouling','Cooling coil fouling','Warm supply air · reduced capacity'),('fan_imbalance','Fan imbalance','High vibration · increased load'),('belt_slip','Drive belt slip','Low airflow · unloaded motor')]
    fault_html=''.join(f'<button class="fault-button" data-fault="{key}" aria-pressed="false"><strong>{label}</strong><span class="fault-state">STANDBY</span><span class="fault-detail">{detail}</span></button>' for key,label,detail in faults)
    script='''<script>
const endpoint='/api/assets/HVAC-001/telemetry',faultEndpoint='/api/assets/HVAC-001/faults',connection=document.querySelector('.connection');let selectedRange='1m',requestId=0,lastFaults=[],selectedDetector='hybrid',lastDetection=null;
const rangeNames={"1m":"1 minute","1h":"1 hour","1d":"1 day"};
function stamp(iso,index,total){const d=new Date(iso),o={hour:'2-digit',minute:'2-digit'};if(selectedRange==='1m')o.second='2-digit';if(selectedRange==='1d'&&(index===0||index===total-1)){o.month='short';o.day='numeric'}return d.toLocaleString([],o)}
function svgNode(name,attrs={}){let n=document.createElementNS('http://www.w3.org/2000/svg',name);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);return n}
function setSeverity(tile,severity){tile.dataset.severity=severity;const led=tile.querySelector('.led');led.setAttribute('role','img');led.setAttribute('aria-label','Status: '+severity)}
function renderFaults(faults){lastFaults=faults;let recovering=0;for(const fault of faults){const button=document.querySelector(`[data-fault="${fault.id}"]`);if(!button)continue;const isRecovering=!fault.active&&fault.level>0;recovering+=isRecovering;button.setAttribute('aria-pressed',String(fault.active));button.dataset.recovering=String(isRecovering);button.querySelector('.fault-state').textContent=fault.active?'ACTIVE':isRecovering?'RECOVERING':'STANDBY'}const active=faults.filter(x=>x.active).length,message=document.querySelector('#fault-message'),reset=document.querySelector('.fault-reset');reset.disabled=!active;message.textContent=active?`${active} injected scenario${active===1?'':'s'} active · effects ramp in over approximately 30 seconds`:recovering?`Recovery in progress · ${recovering} condition${recovering===1?'':'s'} returning to baseline`:'Normal baseline · select a scenario to introduce degradation';message.className='fault-message'}
function safe(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderAlerts(){if(!lastDetection)return;const result=lastDetection[selectedDetector],rows=document.querySelector('#alert-rows'),alerts=result.alerts||[];document.querySelector('#analysis-time').textContent=result.last_analysis_time?'ANALYZED '+new Date(result.last_analysis_time).toLocaleTimeString():'AWAITING ANALYSIS';let max=alerts.reduce((m,a)=>Math.max(m,a.risk_score||0),0),level=max>=80?'critical':max>=55?'warning':'nominal',risk=document.querySelector('#overall-risk');risk.className='maintenance-risk '+level;risk.textContent=alerts.length?`${level.toUpperCase()} · ${max}/100`:(result.model_status||'MONITORING').replaceAll('_',' ').toUpperCase();document.querySelector('#detector-status').textContent=`${selectedDetector.replace('_',' ')} / ${result.status} / ${result.model_status||'ready'}${result.model_confidence!=null?' / model confidence '+result.model_confidence+'%':''}`;if(!alerts.length){rows.innerHTML=`<tr><td class="alert-empty" colspan="7">${result.model_status==='warm_up'||result.model_status==='warming_up'?'Detector warming up on nominal telemetry.':'No persistent anomaly detected. Monitoring baseline and trends.'}</td></tr>`;return}rows.innerHTML=alerts.map(a=>`<tr><td data-label="Severity / risk"><span class="risk-label">${safe(a.severity)} · ${a.risk_score}/100</span><div class="risk-rail" aria-label="Risk ${a.risk_score} out of 100"><i style="width:${Math.max(0,Math.min(100,a.risk_score))}%"></i></div></td><td data-label="Component"><strong>${safe(a.component)}</strong></td><td data-label="Predicted condition">${safe(a.fault_mode)}</td><td data-label="Evidence">${(a.evidence||[]).map(safe).join('<br>')}</td><td data-label="Time remaining"><span class="time-remaining">${safe(a.estimated_time_remaining)}</span></td><td data-label="Confidence"><span class="confidence">${a.confidence}%</span></td><td data-label="Recommendation">${safe(a.recommendation)}</td></tr>`).join('')}
function render(data){const r=data.reading,metrics=document.querySelector('.metrics'),stateTile=document.querySelector('[data-value="state"]').closest('.metric');lastDetection=data.anomaly_detection;renderAlerts();renderFaults(data.faults);metrics.dataset.connection='online';document.querySelector('[data-value="state"]').firstChild.nodeValue=r.state.value;document.querySelector('[data-severity="state"]').textContent=r.state.severity;setSeverity(stateTile,r.state.severity);for(const [key,item] of Object.entries(r.values)){const el=document.querySelector(`[data-value="${key}"]`);el.firstChild.nodeValue=item.value;el.querySelector('.unit').textContent=' '+item.unit;const s=document.querySelector(`[data-severity="${key}"]`);s.textContent=item.severity;setSeverity(s.closest('.metric'),item.severity)}document.querySelectorAll('.plot').forEach(svg=>{svg.querySelectorAll('.trace,.baseline,.axis-label,.y-label,.axis-line,.gridline,.chart-empty').forEach(x=>x.remove());const keys=svg.dataset.series.split(','),configured=Math.max(...keys.map(k=>data.metadata[k].chart_max)),observed=Math.max(...keys.flatMap(k=>data.history.map(x=>x.values[k].value))),max=Math.max(configured,observed),left=48,right=592,top=8,bottom=169,y=v=>bottom-v*(bottom-top)/max,pts=k=>data.history.map((x,i)=>`${left+i*(right-left)/(data.history.length-1)},${y(x.values[k].value)}`).join(' ');[0,.25,.5,.75,1].forEach(f=>{let yy=y(max*f);svg.appendChild(svgNode('line',{x1:left,x2:right,y1:yy,y2:yy,class:'gridline'}));let t=svgNode('text',{x:40,y:yy+3,class:'y-label','text-anchor':'end'});t.textContent=(max*f).toLocaleString([],{maximumFractionDigits:max<10?1:0});svg.appendChild(t)});svg.appendChild(svgNode('line',{x1:left,x2:left,y1:top,y2:bottom,class:'axis-line'}));keys.forEach((key,i)=>{svg.appendChild(svgNode('line',{x1:left,x2:right,y1:y(data.metadata[key].baseline),y2:y(data.metadata[key].baseline),class:'baseline'}));svg.appendChild(svgNode('polyline',{points:pts(key),class:'trace '+(i===1?'alt':i===2?'set':'')}))});[0,Math.floor((data.history.length-1)/2),data.history.length-1].forEach((ix,i)=>{let t=svgNode('text',{x:[left,(left+right)/2,right][i],y:205,class:'axis-label','text-anchor':i===0?'start':i===2?'end':'middle'});t.textContent=stamp(data.history[ix].timestamp,ix,data.history.length);svg.appendChild(t)});let chart=svg.closest('.chart');chart.querySelector('.chart-window').textContent=rangeNames[selectedRange];chart.querySelector('.range-state').textContent=observed>configured?' · range extended':'';let b=chart.querySelector('.baseline-key');b.textContent=keys.map(k=>`${k.replaceAll('_',' ')} ${data.metadata[k].baseline} ${data.metadata[k].unit}`).join(' · ')});connection.className='connection live';document.querySelector('#connection-text').textContent='LIVE';document.querySelector('#updated').textContent='UPDATED '+new Date(r.timestamp).toLocaleTimeString();}
async function poll(){const mine=++requestId,range=selectedRange;try{const res=await fetch(endpoint+'?range='+range,{cache:'no-store'});if(!res.ok)throw Error(res.status);const data=await res.json();if(mine!==requestId||range!==selectedRange)return;render(data)}catch(e){if(mine!==requestId)return;connection.className='connection error';document.querySelector('.metrics').dataset.connection='offline';document.querySelectorAll('.metric').forEach(tile=>{tile.querySelector('.led').setAttribute('aria-label','Status: offline');tile.querySelector('.severity').textContent='Offline · last known'});document.querySelector('#connection-text').textContent='OFFLINE · RETRYING';document.querySelector('#updated').textContent='LAST VALUES RETAINED'}}
async function updateFault(payload){const panel=document.querySelector('.fault-panel'),controls=document.querySelectorAll('.fault-button,.fault-reset'),message=document.querySelector('#fault-message');panel.dataset.busy='true';controls.forEach(x=>x.disabled=true);message.textContent='Applying simulation command…';try{const res=await fetch(faultEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await res.json();if(!res.ok)throw Error(data.error||res.status);renderFaults(data.faults);poll()}catch(e){if(lastFaults.length)renderFaults(lastFaults);message.textContent='Could not update simulation: '+e.message;message.className='fault-message error'}finally{panel.dataset.busy='false';document.querySelectorAll('.fault-button').forEach(x=>x.disabled=false)}}
document.querySelectorAll('.fault-button').forEach(b=>b.addEventListener('click',()=>updateFault({fault_id:b.dataset.fault,active:b.getAttribute('aria-pressed')!=='true'})));document.querySelector('.fault-reset').addEventListener('click',()=>updateFault({reset:true}));document.querySelectorAll('.range-button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.range===selectedRange)return;selectedRange=b.dataset.range;document.querySelectorAll('.range-button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));poll()}));document.querySelectorAll('.detector-tab').forEach(b=>b.addEventListener('click',()=>{selectedDetector=b.dataset.detector;document.querySelectorAll('.detector-tab').forEach(x=>x.setAttribute('aria-selected',String(x===b)));renderAlerts()}));poll();setInterval(poll,1000);
</script>'''
    return page('HVAC-001 Live Twin', f'''<main class="shell"><a class="back" href="/assets">← &nbsp; Asset registry</a><section class="detail-head"><div><p class="eyebrow">Digital twin / Live telemetry</p><h1 class="detail-title">{sid}</h1></div><p class="detail-heading"><span>Plant room · L01</span>Primary air<br>handling unit</p></section><section class="connection" aria-live="polite"><i class="led"></i><span id="connection-text">CONNECTING</span><span class="connection-detail" id="updated">AWAITING FIRST READING</span><span>1 SEC POLL</span></section><section class="fault-panel" aria-labelledby="fault-title"><div class="fault-head"><div><p class="eyebrow">Operator controls / Injected conditions</p><h2 id="fault-title">Simulate fault / degradation</h2><p>Inject equipment conditions and observe telemetry drift from the engineering baseline.</p></div><button class="fault-reset" type="button" disabled>Clear all faults</button></div><div class="fault-grid" role="group" aria-label="Fault simulation controls">{fault_html}</div><p class="fault-message" id="fault-message" role="status" aria-live="polite">Loading simulation state…</p></section><section class="metrics" aria-label="Current readings"><article class="metric state"><span class="metric-label"><i class="led"></i>HVAC state</span><strong class="metric-value" data-value="state">—<small class="unit"></small></strong><span class="severity" data-severity="state">Connecting</span></article>{tiles}</section><header class="chart-controls"><div><h2>Telemetry history</h2><span class="history-note">Historical simulation · UTC source / local display</span></div><div class="range-selector" role="group" aria-label="Chart time range"><button class="range-button" data-range="1m" aria-pressed="true">1 MIN</button><button class="range-button" data-range="1h" aria-pressed="false">1 HOUR</button><button class="range-button" data-range="1d" aria-pressed="false">1 DAY</button></div></header><section class="charts" aria-label="Live telemetry graphs">{graph_html}</section><section class="maintenance" aria-labelledby="maintenance-title"><header class="maintenance-head"><div><p class="eyebrow">Condition intelligence / Risk register</p><h2 id="maintenance-title">Predictive maintenance alerts</h2></div><div class="maintenance-meta"><span class="maintenance-risk" id="overall-risk">MONITORING</span><br><span id="analysis-time">AWAITING ANALYSIS</span></div><p class="maintenance-note"><strong>Simulation estimate</strong> — validate findings and remaining-life estimates before maintenance decisions.</p></header><div class="detector-tabs" role="tablist" aria-label="Anomaly detector result"><button class="detector-tab" role="tab" data-detector="hybrid" aria-selected="true">Hybrid</button><button class="detector-tab" role="tab" data-detector="classic" aria-selected="false">Classic</button><button class="detector-tab" role="tab" data-detector="ai_based" aria-selected="false">AI-based</button></div><div class="alert-wrap"><table class="alert-table"><thead><tr><th>Severity / risk</th><th>Component at risk</th><th>Predicted fault / degradation</th><th>Evidence</th><th>Time remaining</th><th>Confidence</th><th>Predictive maintenance recommendation</th></tr></thead><tbody id="alert-rows"><tr><td class="alert-empty" colspan="7">Connecting to anomaly detectors…</td></tr></tbody></table></div><div class="detector-status" id="detector-status" aria-live="polite">Waiting for first analysis</div></section></main>{script}''')

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed=urlparse(self.path); path = unquote(parsed.path).rstrip('/') or '/'
        if path.startswith('/api/assets/') and path.endswith('/telemetry'):
            asset_id=path[len('/api/assets/'):-len('/telemetry')].rstrip('/')
            ranges=parse_qs(parsed.query).get('range',['1m']); range_key=ranges[0]
            if range_key not in {'1m','1h','1d'}: self.send_json({'error':'invalid range','valid_ranges':['1m','1h','1d']},400); return
            if asset_id == 'HVAC-001':
                payload=SIMULATOR.snapshot_range(range_key); payload['anomaly_detection']=anomaly_detection(payload['reading']); self.send_json(payload); return
            self.send_json({'error':'asset not found','asset_id':asset_id},404); return
        if path in {'/', '/home', '/assets'}: self.send_html(assets_page()); return
        if path.startswith('/digital-twin/'):
            self.send_html(digital_twin_page(path[len('/digital-twin/'):])) if path != '/digital-twin' else self.send_html(page('Not Found',''),404); return
        self.send_html(page('Not Found','<main class="shell notfound"><p class="eyebrow">Error / 404</p><h1>Page not found</h1><a class="back" href="/assets">← Asset registry</a></main>'),404)
    def do_POST(self):
        path=unquote(urlparse(self.path).path).rstrip('/')
        if path != '/api/assets/HVAC-001/faults': self.send_json({'error':'not found'},404); return
        try:
            length=int(self.headers.get('Content-Length','0'))
            if length<=0 or length>4096: raise ValueError('invalid request size')
            payload=json.loads(self.rfile.read(length))
            if not isinstance(payload,dict): raise ValueError('JSON object required')
            if payload.get('reset') is True: faults=SIMULATOR.reset_faults()
            else: faults=SIMULATOR.set_fault(payload.get('fault_id'),payload.get('active'))
        except (ValueError,TypeError,json.JSONDecodeError) as error:
            self.send_json({'error':str(error)},400); return
        self.send_json({'asset_id':'HVAC-001','faults':faults})
    def send_html(self, body, status=200):
        self.send_response(status); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
    def send_json(self, payload, status=200):
        body=json.dumps(payload,separators=(',',':')).encode()
        self.send_response(status); self.send_header('Content-Type','application/json; charset=utf-8'); self.send_header('Cache-Control','no-store, max-age=0'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
    def log_message(self, format, *args): print(f'{self.address_string()} - {format % args}')

if __name__ == '__main__':
    server=ThreadingHTTPServer((HOST,PORT),RequestHandler); print(f'Serving on http://{HOST}:{PORT}')
    try: server.serve_forever()
    except KeyboardInterrupt: print('\nStopping server')
    finally: server.server_close()
